ControlPropertyState.AutoRuleBindingString:
Set(varMonthStart, Date(Year(Now()), Month(Now()), 1));
Set(varKpiRejectedAll,
    CountRows(Filter(CentralDepositMainList, Status.Value = "Rejected")));
Set(varKpiRejectedMonth,
    CountRows(Filter(CentralDepositMainList, Status.Value = "Rejected", Created >= varMonthStart)));
Set(varKpiMyMonthTotal,
    CountRows(Filter(CentralDepositMainList, 'Created By'.Email = User().Email, Created >= varMonthStart)));
Set(varKpiMyMonthSuccess,
    CountRows(Filter(CentralDepositMainList, 'Created By'.Email = User().Email, Created >= varMonthStart, Status.Value = "Approved")));
Set(varKpiAllMonthTotal,
    CountRows(Filter(CentralDepositMainList, Created >= varMonthStart)));
Set(varKpiAllMonthSuccess,
    CountRows(Filter(CentralDepositMainList, Created >= varMonthStart, Status.Value = "Approved")));
Set(varKpiAvgPublishDays,
    With(
        {approved: Filter(CentralDepositMainList, Status.Value = "Approved", Not(IsBlank(PublicationDate)))},
        If(CountRows(approved) = 0,
            Blank(),
            Round(
                Average(AddColumns(approved, "durHours",
                    DateDiff(Created, PublicationDate, TimeUnit.Hours)),
                    durHours) / 24,
                1))))
